package com.hbm.client.radiolysis;
import com.hbm.machine.radiolysis.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
/** Resource heat and source energy-control output; no invented processing progress. */
@WailaPlugin public final class RadiolysisJadePlugin implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Provider.INSTANCE,RadiolysisBlockEntity.class);event.registerBlockDataProvider(Provider.INSTANCE,RadiolysisPort.class);}
 @Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Provider.INSTANCE,RadiolysisBlock.class);}
 private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return RadiolysisContent.id("radiolysis_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){var tile=accessor.getBlockEntity();if(tile instanceof RadiolysisPort&&accessor.getBlockState().getBlock() instanceof RadiolysisBlock block){var pos=block.findCore(accessor.getLevel(),accessor.getPosition());tile=pos==null?null:accessor.getLevel().getBlockEntity(pos);}if(tile instanceof RadiolysisBlockEntity machine){tag.putInt("hbm:radiolysis_heat",machine.heat);}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){var tag=accessor.getServerData();if(!tag.contains("hbm:radiolysis_heat"))return;int heat=tag.getInt("hbm:radiolysis_heat");tooltip.add(Component.translatable("desc.gui.rtg.heat",heat));tooltip.add(Component.translatable("jade.hbm.radiolysis.output",heat*10));}}
}
